 async function loadHistory(refresh=false){if(historyTask)return historyTask;if(historyAttempted&&!refresh)return;historyAttempted=true;historyTask=(async()=>{try{const manifest=await request('/api/stock-forecast?part=manifest'+(refresh?'&refresh=1':''));let done=0,cursor=0;const months=manifest.period.months;await Promise.all(Array.from({length:2},async()=>{while(cursor<months.length){const month=months[cursor++];try{let page=1;do{const chunk=await request('/api/stock-forecast?'+new URLSearchParams({part:'history',month,page,...(refresh?{refresh:'1'}:{})}));page=chunk.nextPage;}while(page);}catch{}finally{state.historyNote='อ่านประวัติขายแล้ว '+(++done)+' / 6 เดือน';if(state.loading){source();table();}}}}));}catch{state.historyNote='ยังอ่าน DOH ไม่ได้ · จะใช้เกณฑ์สต็อกระดับต่ำ';}})().finally(()=>historyTask=null);return historyTask;}
 async function loadStock(refresh=false){const retained=[...state.selected.values()],retainedPricing=new Map(state.pricing);const serial=++state.serial;state.loading=true;state.error='';state.page=1;state.historyNote='กำลังอ่าน DOH จากคาดการณ์สินค้าขาด';draw();try{await loadHistory(refresh);if(serial!==state.serial)return;const url=new URL('/api/promotions/stock',location.origin);url.searchParams.set('channel',state.channel);if(state.scope==='branch'&&state.branchId)url.searchParams.set('branchId',state.branchId);if(refresh)url.searchParams.set('refresh','1');state.historyNote='กำลังรวมสต็อกเป็นรุ่นและจับคู่ต้นทุน';source();table();const stock=await request(url);if(serial!==state.serial)return;state.stock=stock;}catch(e){if(serial!==state.serial)return;state.stock=null;state.error=e.message;}finally{if(serial===state.serial){state.loading=false;state.pricing=retainedPricing;if(retained?.length){if(state.error)state.selected=new Map(retained.map(r=>[r.key,r]));else restoreSelected(retained);}state.pricing=new Map([...retainedPricing,...state.pricing]);draw();}}}
