 function policy(){const p=state.policy;$('[data-policy-body]').innerHTML=`<div class="pm-dialog-header"><div><p class="pm-eyebrow">STOCK → DISCOUNT</p><h2>เกณฑ์เสนอส่วนลด</h2></div><button data-promo-control data-close aria-label="ปิด">×</button></div><p class="pm-dialog-intro">ค่าเริ่มต้นเป็นเกณฑ์จำลองสำหรับออกแบบข้อเสนอ ปรับให้เหมาะกับธุรกิจและให้ผู้รับผิดชอบพิจารณาก่อนใช้จริง</p><form data-policy-form><div class="pm-policy-thresholds">${p.thresholds.map((n,i)=>`<label>ขอบบนระดับ ${i+1} (หน่วย)<input data-promo-control type="number" name="threshold-${i}" min="1" max="100000" value="${n}" required></label>`).join('')}</div><h3>เกณฑ์ DOH (วัน)</h3><div class="pm-policy-doh">${p.doh.map((n,i)=>`<label>${['ใกล้ขาด / ไม่ลด','DOH ระดับ 1','DOH ระดับ 2','DOH ระดับ 3'][i]}<input data-promo-control name="doh-${i}" type="number" min="1" max="3650" value="${n}" required></label>`).join('')}</div><div class="pm-policy-table"><div class="pm-policy-table-head"><span>ส่วนลดตามระดับสต็อก</span>${tiers.map(t=>`<span>${t}</span>`).join('')}</div>${['department','fast'].map(f=>`<div><strong>${f==='department'?'Department + Event GP':'Standalone + Event เก็บเอง'}</strong>${p[f].map((n,i)=>`<label><span class="pm-sr">${f} ${tiers[i]}</span><input data-promo-control name="${f}-${i}" type="number" min="0" max="100" step="any" value="${n}" required><span>%</span></label>`).join('')}</div>`).join('')}</div><div class="pm-policy-example">คำนวณต่อรุ่นและเกรด · ภาพรวมใช้จำนวนเฉลี่ยต่อสาขา · เลือกส่วนลดต่ำกว่าระหว่างระดับ Stock และ DOH · ไซซ์ไม่พบขายใช้เกณฑ์ Stock โดยไม่เกิน 100%<br>กลุ่มรับเงินเองต้องลดไม่น้อยกว่ากลุ่ม Department และทุกระดับต้องไม่เกิน 100%</div><p data-policy-error class="pm-error" hidden role="alert"></p><button class="pm-button pm-primary" data-promo-control type="submit">ใช้เกณฑ์นี้กับข้อเสนอ</button></form>`;openDialog(policyDialog);}
