 function beginPlanAction(id,action){
  const plan=state.plans.find(p=>p.id===id);
  if(!plan||state.busy||!state.permissions.canEdit||action==='approve'&&!state.permissions.canApprove)return;
  savedFeedback='';savedAction={id,action,revision:plan.revision||1,pending:false,error:''};savedList();
  $('[data-action="cancel-plan-action"]')?.focus({preventScroll:true});
 }
 async function confirmPlanAction(){
  if(!savedAction||savedAction.pending||state.busy)return;
  const action=savedAction;savedAction.pending=true;state.busy=true;savedList();updateSaveButtons();
  try{
   const result=await request('/api/promotions/'+(action.action==='approve'?'approval':'delete'),{id:action.id,expectedVersion:action.revision});
   if(result.plan)state.plans=state.plans.map(p=>p.id===result.plan.id?result.plan:p);
   else state.plans=state.plans.filter(p=>p.id!==result.deletedId);
   state.busy=false;if(state.editing?.id===action.id)cancelEdit();
   savedAction=null;savedFeedback='';toast(action.action==='approve'?'อนุมัติข้อเสนอแล้ว':'ลบข้อเสนอแล้ว');
  }catch(e){
   savedAction.pending=false;savedAction.error=e.message;toast(e.message,true);
   if([404,409].includes(e.status)){try{const latest=await request('/api/promotions');state.plans=latest.plans;state.permissions=latest.permissions;savedFeedback=e.message;savedAction=null;}catch{}}
  }finally{state.busy=false;updateSaveButtons();months();$('[data-plan-count]').textContent=state.plans.length;savedList();focusSaved(action.id);}
 }
 savedDialog.addEventListener('cancel',event=>{if(savedAction?.pending)event.preventDefault();});
