  activeBrief=structuredClone({id:plan?.id,conditions:plan?(plan.conditions||''):state.conditions,name:plan?.name||state.name||'สรุปโปรโมชั่น '+monthLabel(month),month,channel,
   gp:plan?(plan.gp??null):channels[channel].family==='department'?(state.gp===''?null:Number(state.gp)):0,
   branchName:plan?(plan.branchName||'ภาพรวมประเภท'):(state.stock?.branches.find(b=>b.id===state.branchId)?.name||'ภาพรวมประเภท'),
   forecast:plan?plan.forecast:state.stock?.forecast,createdAt:plan?.createdAt,updatedAt:plan?.updatedAt,status:plan?.status,approval:plan?.approval,approvedAt:plan?.approvedAt,promotionType:plan?plan.promotionType:state.promotionType,startDate:plan?plan.startDate:state.startDate,endDate:plan?plan.endDate:state.endDate,event:plan?plan.event:state.event,lines});
  $('[data-saved-body]').innerHTML=renderPromotionBrief(activeBrief,{canEdit:!!plan&&state.permissions.canEdit&&['draft','proposed'].includes(plan.status)&&plan.approval==='unapproved'});
  savedDialog.setAttribute('aria-label','สรุปโปรโมชั่นหน้าเดียว');
