 function planDetail(id){const plan=state.plans.find(p=>p.id===id);if(plan)showPromotionSummary(plan);}
 function showSizes(key){
  const row=currentRows().find(r=>r.key===key);if(!row)return;
  const sizes=new Map();
  for(const r of row.members){
   const size=String(r.size??''),color=String(r.color??''),k=JSON.stringify([size,color]);
   if(!sizes.has(k))sizes.set(k,{size,color,available:0,sold:0,daily:0,known:true});
   const item=sizes.get(k);item.available+=r.available;item.sold+=r.sold||0;item.daily+=r.daily||0;item.known&&=r.historyKnown;
  }
  const rows=[...sizes.values()],compare=(a,b)=>a.localeCompare(b,'th',{numeric:true}),choices=field=>[...new Set(rows.map(r=>r[field]))].sort(compare);
  const colors=choices('color'),sizeOptions=choices('size');
  const options=(values,emptyLabel)=>values.map((value,i)=>`<option value="${i}">${esc(value||emptyLabel)}</option>`).join('');
  $('[data-saved-body]').innerHTML=`<div class="pm-size-details"><div class="pm-dialog-header"><div><p class="pm-eyebrow">MODEL / SIZE DETAILS</p><h2>${esc(row.model)} · ${esc(row.grade)}</h2><p>${row.noSales?'รายการนี้เลือกเฉพาะไซซ์ไม่พบยอดขาย':'รายการนี้รวมไซซ์ปกติของรุ่น'}</p></div><button data-promo-control data-close aria-label="ปิด">×</button></div><div class="pm-size-filters" role="group" aria-label="กรองรายละเอียดรุ่นและไซซ์"><label>สี<select data-promo-control data-size-filter="color"><option value="">ทุกสี</option>${options(colors,'ไม่ระบุสี')}</select></label><label>ไซซ์<select data-promo-control data-size-filter="size"><option value="">ทุกไซซ์</option>${options(sizeOptions,'ไม่ระบุไซซ์')}</select></label><label>สถานะสต็อก<select data-promo-control data-size-filter="stock"><option value="">ทั้งหมด</option><option value="available">มีสต็อกพร้อมขาย</option><option value="empty">ไม่มีสต็อกพร้อมขาย</option></select></label></div><div class="pm-size-results"><p data-size-count role="status" aria-live="polite" aria-atomic="true"></p><button class="pm-button pm-outline" data-promo-control data-size-reset>ล้างตัวกรอง</button></div><div class="pm-table-wrap pm-size-table-wrap" tabindex="0" role="region" aria-label="ตารางสต็อกแยกสีและไซซ์"><table class="pm-table pm-size-table"><thead><tr><th scope="col">ไซซ์</th><th scope="col">สี</th><th scope="col">พร้อมขาย</th><th scope="col">ขายย้อนหลัง</th><th scope="col">DOH</th></tr></thead><tbody data-size-rows></tbody></table></div><p class="pm-calculation-note">${esc(promotionReason(row,state.policy))} · ${esc(state.stock.sourceLabel)}</p></div>`;
  const detail=$('.pm-size-details'),filters=[...detail.querySelectorAll('[data-size-filter]')],reset=detail.querySelector('[data-size-reset]');
  function filterSizes(){
   const [color,size,stock]=filters.map(n=>n.value);
   const visible=rows.filter(r=>(color===''||r.color===colors[Number(color)])&&(size===''||r.size===sizeOptions[Number(size)])&&(stock===''||(stock==='available'?r.available>0:r.available<=0)));
   detail.querySelector('[data-size-rows]').innerHTML=visible.length?visible.map(r=>`<tr><td>${esc(r.size||'ไม่ระบุไซซ์')}</td><td>${esc(r.color||'ไม่ระบุสี')}</td><td>${number(r.available)}</td><td>${r.known?number(r.sold):'ข้อมูลยังไม่ครบ'}</td><td>${r.known&&r.daily>0?number(r.available/r.daily)+' วัน':r.known?'ไม่พบขาย':'—'}</td></tr>`).join(''):'<tr><td colspan="5" class="pm-size-empty">ไม่พบรายการตามตัวกรองที่เลือก</td></tr>';
   detail.querySelector('[data-size-count]').textContent=`แสดง ${number(visible.length)} จาก ${number(rows.length)} รายการ · พร้อมขาย ${number(visible.reduce((sum,r)=>sum+r.available,0))} หน่วย`;
   reset.disabled=filters.every(n=>n.value==='');
   detail.querySelector('.pm-size-table-wrap').scrollTop=0;
  }
  detail.querySelector('.pm-size-filters').addEventListener('change',filterSizes);
  reset.addEventListener('click',()=>{for(const filter of filters)filter.value='';filterSizes();filters[0].focus();});
  filterSizes();openDialog(savedDialog,`รายละเอียด ${row.model} · ${row.grade}`);
 }
