   state.selected.clear();state.pricing.clear();state.name='';state.conditions='';state.confirmed=false;state.editing=null;state.promotionType='general';state.startDate='';state.endDate='';state.eventId='';state.event=null;state.eventVersion='';previousWork=null;draw();drafts.capture();await drafts.flush();
   message.textContent=editing?'บันทึกการแก้ไขแล้ว · อัปเดตข้อเสนอเดิม':'บันทึกแล้ว · เปิดดูได้ในข้อเสนอที่บันทึก';toast(editing?'บันทึกการแก้ไขแล้ว':'บันทึกข้อเสนอแล้ว');
   if(editing)showPromotionSummary(result.plan);
